/* FreeFanRadio player and page behaviour.
 *
 * Data comes from window.FFR_STATIONS and window.FFR_TEAMS (generated by Jekyll,
 * see _includes/stations-data.html). Everything uses event delegation, so pages
 * swapped in by the SPA router need no re-binding; the audio keeps playing.
 *
 * Saved in this browser only (localStorage):
 *   freefanradio_recent_stations  [{ id, lastPlayed }]   recently played stations
 *   ffr_my_teams                  ["team-slug", ...]      teams the listener follows
 *   ffr_last                      { id, team }            last station, for one-tap resume
 */
(function () {
    'use strict';

    // ---------- Data ----------
    const stations = () => window.FFR_STATIONS || {};
    const teams = () => window.FFR_TEAMS || {};
    const station = (id) => stations()[id] || null;
    const team = (slug) => (slug && teams()[slug]) || null;

    const store = {
        get(key, fallback) {
            try {
                const v = localStorage.getItem(key);
                return v ? JSON.parse(v) : fallback;
            } catch (e) { return fallback; }
        },
        set(key, value) {
            try { localStorage.setItem(key, JSON.stringify(value)); } catch (e) { /* private mode */ }
        }
    };

    const RECENT_KEY = 'freefanradio_recent_stations';
    const TEAMS_KEY = 'ffr_my_teams';
    const LAST_KEY = 'ffr_last';
    const MAX_RECENT = 8;

    function recentIds() {
        const raw = store.get(RECENT_KEY, []);
        if (!Array.isArray(raw)) return [];
        const seen = new Set();
        const ids = [];
        for (const item of raw) {
            let id = item && item.id;
            if (!station(id) && item) {
                // Older entries stored a name/url instead of an id
                const match = Object.values(stations()).find(s => s.url === item.url || s.name === item.name);
                id = match && match.id;
            }
            if (id && station(id) && !seen.has(id)) { seen.add(id); ids.push(id); }
        }
        return ids.slice(0, MAX_RECENT);
    }

    function pushRecent(id) {
        const ids = [id].concat(recentIds().filter(x => x !== id)).slice(0, MAX_RECENT);
        const now = new Date().toISOString();
        store.set(RECENT_KEY, ids.map(x => ({ id: x, lastPlayed: now })));
    }

    function myTeams() {
        const list = store.get(TEAMS_KEY, []);
        return Array.isArray(list) ? list.filter(slug => team(slug)) : [];
    }

    function setFollow(slug, on) {
        const list = myTeams().filter(s => s !== slug);
        if (on) list.push(slug);
        store.set(TEAMS_KEY, list);
    }

    const firstStationOf = (slug) => {
        const t = team(slug);
        return t && t.stations.find(id => station(id)) || null;
    };

    // ---------- Small UI helpers ----------
    const $ = (sel, root) => (root || document).querySelector(sel);
    const $$ = (sel, root) => Array.from((root || document).querySelectorAll(sel));

    function escapeHtml(s) {
        return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    }

    let toastTimer = null;
    function toast(message) {
        let el = $('#ffrToast');
        if (!el) {
            el = document.createElement('div');
            el.id = 'ffrToast';
            el.className = 'toast';
            el.setAttribute('role', 'status');
            document.body.appendChild(el);
        }
        el.textContent = message;
        el.hidden = false;
        clearTimeout(toastTimer);
        toastTimer = setTimeout(() => { el.hidden = true; }, 3000);
    }

    const ICON_PLAY = '<svg class="i-play" width="22" height="22" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M7 4.5v15l13-7.5z"/></svg>';
    const ICON_PAUSE = '<svg class="i-pause" width="22" height="22" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M6 4h4v16H6zM14 4h4v16h-4z"/></svg>';

    // ---------- Player ----------
    const player = {
        audio: new Audio(),
        stationId: null,
        teamSlug: null,
        status: 'idle', // idle | loading | live | paused | error
        pending: false,  // a play() is connecting

        init() {
            this.audio.preload = 'none';
            const a = this.audio;
            a.addEventListener('playing', () => { this.pending = false; this.setStatus('live'); });
            a.addEventListener('waiting', () => { if (this.status !== 'paused') this.setStatus('loading'); });
            a.addEventListener('stalled', () => { if (this.status === 'live') this.setStatus('loading'); });
            // Changing src fires a 'pause' while we are connecting; ignore it until playback starts
            a.addEventListener('pause', () => { if (!this.pending && this.status !== 'error') this.setStatus('paused'); });
            a.addEventListener('error', () => {
                if (!a.getAttribute('src')) return; // we cleared src ourselves
                this.pending = false;
                this.setStatus('error');
            });

            if ('mediaSession' in navigator) {
                const ms = navigator.mediaSession;
                const safe = (action, fn) => { try { ms.setActionHandler(action, fn); } catch (e) { /* unsupported */ } };
                safe('play', () => this.resume());
                safe('pause', () => this.pause());
                safe('stop', () => this.pause());
                safe('previoustrack', () => this.skip(-1));
                safe('nexttrack', () => this.skip(1));
            }

            // Show the last station, paused, so returning listeners resume in one tap
            const last = store.get(LAST_KEY, null);
            if (last && station(last.id)) {
                this.stationId = last.id;
                this.teamSlug = team(last.team) ? last.team : null;
                this.setStatus('paused');
            }
        },

        play(id, teamSlug) {
            const s = station(id);
            if (!s) return;
            this.stationId = id;
            this.teamSlug = team(teamSlug) ? teamSlug : null;
            store.set(LAST_KEY, { id, team: this.teamSlug });
            pushRecent(id);
            this.start();
            renderHome();
        },

        start() {
            const s = station(this.stationId);
            if (!s) return;
            // Always (re)connect to the live edge instead of resuming a stale buffer
            this.pending = true;
            this.audio.src = s.url;
            this.setStatus('loading');
            const p = this.audio.play();
            if (p && p.catch) {
                p.catch(err => {
                    if (err && err.name === 'NotAllowedError') {
                        this.pending = false;
                        this.setStatus('paused');
                        toast('Tap play to start listening');
                    } else if (err && err.name !== 'AbortError') {
                        this.pending = false;
                        this.setStatus('error');
                    }
                });
            }
            if (typeof gtag === 'function') gtag('event', 'play_station', { station_id: this.stationId, team: this.teamSlug || '' });
        },

        pause() {
            this.pending = false;
            this.setStatus('paused');
            this.audio.pause();
            // Drop the connection so we don't keep downloading a live stream
            this.audio.removeAttribute('src');
            this.audio.load();
        },

        resume() { if (this.stationId) this.start(); },

        toggle() {
            if (!this.stationId) return;
            if (this.status === 'live' || this.status === 'loading') this.pause();
            else this.resume();
        },

        // Followed teams first, then recent stations; one entry per station
        queue() {
            const items = [];
            const seen = new Set();
            for (const slug of myTeams()) {
                const id = firstStationOf(slug);
                if (id && !seen.has(id)) { seen.add(id); items.push({ id, team: slug }); }
            }
            for (const id of recentIds()) {
                if (!seen.has(id)) { seen.add(id); items.push({ id, team: null }); }
            }
            return items;
        },

        skip(dir) {
            const q = this.queue();
            if (q.length < 2) return;
            let i = q.findIndex(x => x.id === this.stationId);
            i = i === -1 ? 0 : (i + dir + q.length) % q.length;
            this.play(q[i].id, q[i].team);
        },

        setStatus(status) {
            this.status = status;
            this.render();
        },

        headline() {
            const t = team(this.teamSlug);
            const s = station(this.stationId);
            return t ? t.name : (s ? s.name : '');
        },

        render() {
            const s = station(this.stationId);
            document.body.classList.toggle('has-player', !!s);
            if (!s) return;
            const t = team(this.teamSlug);
            const statusText = {
                idle: 'Ready', loading: 'Connecting…', live: 'Live', paused: 'Paused · tap play to resume',
                error: 'Stream unavailable · tap play to retry'
            }[this.status];

            for (const el of [$('#miniPlayer'), $('#fullPlayer')]) {
                if (!el) continue;
                el.classList.toggle('is-live', this.status === 'live');
                el.classList.toggle('is-loading', this.status === 'loading');
            }
            $$('[data-player-title]').forEach(el => { el.textContent = this.headline(); });
            $$('[data-player-status]').forEach(el => {
                el.textContent = t && this.status === 'live' ? 'Live · ' + s.name : statusText;
            });
            $$('[data-player-headline]').forEach(el => { el.textContent = this.headline(); });
            $$('[data-player-sub]').forEach(el => {
                el.textContent = t ? s.name : [s.frequency, s.location].filter(Boolean).join(' · ');
            });
            $$('[data-player-badge]').forEach(el => {
                el.textContent = { live: 'Live', loading: 'Connecting', paused: 'Paused', error: 'Unavailable', idle: 'Ready' }[this.status];
            });
            $$('[data-player-toggle]').forEach(el => {
                el.setAttribute('aria-label', this.status === 'live' || this.status === 'loading' ? 'Pause' : 'Play');
            });

            // Next-up list and skip buttons
            const q = this.queue().filter(x => x.id !== this.stationId);
            $$('[data-player-prev], [data-player-next]').forEach(b => { b.disabled = q.length === 0; });
            const wrap = $('[data-player-next-wrap]');
            const list = $('[data-player-next-list]');
            if (wrap && list) {
                wrap.hidden = q.length === 0;
                list.innerHTML = q.slice(0, 4).map(x => {
                    const xs = station(x.id);
                    const xt = team(x.team);
                    return '<button type="button" class="fp-next-item play-station-btn" data-station-id="' + escapeHtml(x.id) + '"' +
                        (xt ? ' data-team="' + escapeHtml(xt.slug) + '"' : '') + '><span>' + escapeHtml(xt ? xt.name : xs.name) +
                        '</span><span>' + escapeHtml(xt ? xs.name : 'Recent') + '</span></button>';
                }).join('');
            }

            this.renderButtons();

            if ('mediaSession' in navigator && window.MediaMetadata) {
                navigator.mediaSession.metadata = new MediaMetadata({
                    title: this.headline(),
                    artist: t ? s.name : 'Live radio',
                    album: 'FreeFanRadio',
                    artwork: [96, 192, 256, 512].map(n => ({ src: '/assets/icons/artwork-' + n + '.png', sizes: n + 'x' + n, type: 'image/png' }))
                });
                try { navigator.mediaSession.playbackState = this.status === 'live' || this.status === 'loading' ? 'playing' : 'paused'; } catch (e) { /* old browsers */ }
            }
            document.dispatchEvent(new CustomEvent('ffr:player'));
        },

        // Reflect the current state on every Play button on the page
        renderButtons() {
            const active = this.status === 'live' || this.status === 'loading';
            $$('.play-station-btn').forEach(btn => {
                if (btn.classList.contains('fp-next-item')) return;
                const sameStation = btn.dataset.stationId === this.stationId;
                const sameTeam = !btn.dataset.team || !this.teamSlug || btn.dataset.team === this.teamSlug;
                const on = active && sameStation && sameTeam;
                btn.classList.toggle('is-playing', on);
                const label = btn.querySelector('[data-label]');
                if (label) label.textContent = on ? 'Playing · tap to pause' : 'Play live';
                const card = btn.closest('.team-card');
                if (card) card.classList.toggle('is-playing', on);
            });
        }
    };

    // ---------- Full-screen player ----------
    const fullPlayer = {
        el: null,
        open() {
            if (!this.el || !player.stationId) return;
            this.el.classList.add('open');
            document.body.classList.add('player-open');
            history.pushState({ ffrPlayer: true }, '', location.href);
            const close = $('[data-player-close]', this.el);
            if (close) close.focus();
        },
        isOpen() { return !!this.el && this.el.classList.contains('open'); },
        hide() {
            if (!this.el) return;
            this.el.classList.remove('open');
            document.body.classList.remove('player-open');
        },
        close() {
            if (!this.isOpen()) return;
            if (history.state && history.state.ffrPlayer) history.back(); // popstate hides it
            else this.hide();
        }
    };

    // ---------- Resume screen ----------
    // Shown when the installed app opens on the home page, or from the
    // "Resume last station" shortcut (/?resume=1). Phones need one tap before
    // sound can play, so that tap is the biggest button on screen.
    const resumeScreen = {
        el: null,
        shouldShow() {
            if (!player.stationId || player.status === 'live') return false;
            const params = new URLSearchParams(location.search);
            if (params.get('resume') === '1') return true;
            const standalone = (window.matchMedia && matchMedia('(display-mode: standalone)').matches) || navigator.standalone === true;
            let shown = false;
            try { shown = sessionStorage.getItem('ffr_resume_shown') === '1'; } catch (e) { /* ignore */ }
            return standalone && !shown && location.pathname === '/';
        },
        show() {
            if (!this.el) return;
            try { sessionStorage.setItem('ffr_resume_shown', '1'); } catch (e) { /* ignore */ }
            const s = station(player.stationId);
            const t = team(player.teamSlug);
            $('[data-resume-title]', this.el).textContent = player.headline();
            $('[data-resume-sub]', this.el).textContent = (t ? s.name + ' · ' : '') + 'tap to listen';
            const more = player.queue().filter(x => x.id !== player.stationId).slice(0, 2);
            $('[data-resume-more]', this.el).innerHTML = more.map(x => {
                const xs = station(x.id);
                const xt = team(x.team);
                return '<button type="button" class="fp-next-item play-station-btn" data-station-id="' + escapeHtml(x.id) + '"' +
                    (xt ? ' data-team="' + escapeHtml(xt.slug) + '"' : '') + '><span>' + escapeHtml(xt ? xt.name : xs.name) +
                    '</span><span>' + escapeHtml(xt ? xs.name : 'Recent') + '</span></button>';
            }).join('');
            this.el.hidden = false;
            document.body.classList.add('resume-open');
            const go = $('[data-resume-go]', this.el);
            if (go) go.focus();
        },
        hide() {
            if (!this.el || this.el.hidden) return;
            this.el.hidden = true;
            document.body.classList.remove('resume-open');
        }
    };

    // ---------- Sharing ----------
    function share() {
        const s = station(player.stationId);
        if (!s) return;
        const t = team(player.teamSlug);
        const url = location.origin + (t ? t.page : '/') + '?radioId=' + encodeURIComponent(s.id);
        const text = 'Listen to ' + (t ? t.name + ' on ' : '') + s.name + ' live on FreeFanRadio';
        if (navigator.share) {
            navigator.share({ title: text, url }).catch(() => {});
        } else if (navigator.clipboard) {
            navigator.clipboard.writeText(url).then(() => toast('Link copied'), () => toast(url));
        } else {
            toast(url);
        }
    }

    // ---------- Page features (run on load and after every SPA navigation) ----------
    function renderHome() {
        const cards = $('[data-my-teams]');
        if (cards) {
            const followed = myTeams();
            cards.innerHTML = followed.map(slug => {
                const t = team(slug);
                const id = firstStationOf(slug);
                const s = station(id);
                return '<div class="team-card">' +
                    '<a class="team-card-main" href="' + escapeHtml(t.page) + '">' +
                    '<span class="eyebrow">' + escapeHtml(t.league) + '</span>' +
                    '<span class="team-card-name">' + escapeHtml(t.name) + '</span>' +
                    '<span class="team-card-sub">' + escapeHtml(s ? s.name : 'No live stream yet') + '</span></a>' +
                    (s ? '<button type="button" class="play-circle play-station-btn" data-station-id="' + escapeHtml(id) +
                        '" data-team="' + escapeHtml(slug) + '" aria-label="Play ' + escapeHtml(t.name) + '">' +
                        ICON_PLAY.replace(/22/g, '30') + ICON_PAUSE.replace(/22/g, '28') + '</button>' : '') +
                    '</div>';
            }).join('');
            const empty = $('[data-my-teams-empty]');
            if (empty) empty.hidden = followed.length > 0;
        }

        const recentWrap = $('[data-recent-wrap]');
        const recent = $('[data-recent]');
        if (recentWrap && recent) {
            const ids = recentIds();
            recentWrap.hidden = ids.length === 0;
            recent.innerHTML = ids.map(id => '<button type="button" class="chip play-station-btn" data-station-id="' +
                escapeHtml(id) + '">' + escapeHtml(station(id).name) + '</button>').join('');
        }
        player.renderButtons();
    }

    function renderFollowButtons() {
        const followed = new Set(myTeams());
        $$('[data-follow-team]').forEach(btn => {
            const on = followed.has(btn.dataset.followTeam);
            btn.setAttribute('aria-pressed', on ? 'true' : 'false');
            const label = btn.querySelector('[data-follow-label]');
            if (label) label.textContent = on ? 'In your teams' : 'Add to your teams';
        });
    }

    const search = { league: '' };
    function applyTeamSearch() {
        const root = $('[data-team-search]');
        if (!root) return;
        const input = $('[data-search-input]', root);
        const norm = s => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
        const q = input ? norm(input.value.trim()) : '';
        let any = false;
        $$('.league-section', root).forEach(sec => {
            const leagueOk = !search.league || sec.dataset.league === search.league;
            let shown = 0;
            $$('li[data-search]', sec).forEach(li => {
                const hit = leagueOk && (!q || norm(li.dataset.search).includes(q));
                li.hidden = !hit;
                if (hit) shown++;
            });
            sec.hidden = shown === 0;
            if (shown) any = true;
        });
        $$('[data-league-filter]', root).forEach(b => b.setAttribute('aria-pressed', b.dataset.leagueFilter === search.league ? 'true' : 'false'));
        const empty = $('[data-search-empty]', root);
        if (empty) empty.hidden = any;
    }

    function initPage() {
        search.league = '';
        renderHome();
        renderFollowButtons();
        applyTeamSearch();
        player.renderButtons();
        document.dispatchEvent(new CustomEvent('ffr:page'));
    }

    // ---------- SPA navigation (keeps audio playing between pages) ----------
    const router = {
        busy: false,

        shouldHandle(a, e) {
            if (!a || e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return false;
            if (a.target || a.hasAttribute('download') || a.origin !== location.origin) return false;
            if (/\.(xml|json|txt|pdf|png|jpe?g|svg|ico|mp3|aac)$/i.test(a.pathname)) return false;
            if (a.hash && a.pathname === location.pathname) return false;
            return true;
        },

        async go(url, push) {
            if (this.busy) return;
            this.busy = true;
            document.body.classList.add('spa-loading');
            try {
                const res = await fetch(url, { credentials: 'same-origin' });
                if (!res.ok) throw new Error('HTTP ' + res.status);
                const doc = new DOMParser().parseFromString(await res.text(), 'text/html');
                const next = doc.querySelector('#main');
                const main = $('#main');
                if (!next || !main) throw new Error('No main content');
                if (push) history.pushState({}, '', url);
                document.title = doc.title;
                main.innerHTML = next.innerHTML;
                // Inline scripts in swapped content don't run on their own
                $$('script', main).forEach(old => {
                    if (old.type && old.type !== 'text/javascript') return;
                    const s = document.createElement('script');
                    s.textContent = old.textContent;
                    old.replaceWith(s);
                });
                this.updateNav();
                window.scrollTo(0, 0);
                main.setAttribute('tabindex', '-1');
                main.focus({ preventScroll: true });
                initPage();
                if (typeof gtag === 'function') gtag('event', 'page_view', { page_location: location.href, page_title: document.title });
            } catch (err) {
                location.href = url;
            } finally {
                this.busy = false;
                document.body.classList.remove('spa-loading');
            }
        },

        updateNav() {
            const path = location.pathname;
            $$('[data-nav]').forEach(a => {
                const nav = a.dataset.nav;
                const on = nav === '/' ? path === '/' :
                    path.startsWith(nav) || (nav === '/sports/' && path.startsWith('/stations/'));
                a.classList.toggle('active', on);
            });
        }
    };

    // ---------- Events (delegated) ----------
    document.addEventListener('click', (e) => {
        const playBtn = e.target.closest('.play-station-btn');
        if (playBtn) {
            e.preventDefault();
            if (resumeScreen.el && !resumeScreen.el.hidden) resumeScreen.hide();
            const id = playBtn.dataset.stationId;
            const slug = playBtn.dataset.team || null;
            const isCurrent = id === player.stationId && (!slug || slug === player.teamSlug);
            if (isCurrent && (player.status === 'live' || player.status === 'loading')) player.pause();
            else player.play(id, slug || (id === player.stationId ? player.teamSlug : null));
            return;
        }
        if (e.target.closest('[data-player-toggle]')) { player.toggle(); return; }
        if (e.target.closest('[data-player-open]')) { fullPlayer.open(); return; }
        if (e.target.closest('[data-player-close]')) { fullPlayer.close(); return; }
        if (e.target.closest('[data-player-prev]')) { player.skip(-1); return; }
        if (e.target.closest('[data-player-next]')) { player.skip(1); return; }
        if (e.target.closest('[data-player-share]')) { share(); return; }
        if (e.target.closest('[data-resume-go]')) { resumeScreen.hide(); player.resume(); fullPlayer.open(); return; }
        if (e.target.closest('[data-resume-dismiss]')) { resumeScreen.hide(); return; }

        const follow = e.target.closest('[data-follow-team]');
        if (follow) {
            const slug = follow.dataset.followTeam;
            const on = !myTeams().includes(slug);
            setFollow(slug, on);
            renderFollowButtons();
            renderHome();
            player.render();
            document.dispatchEvent(new CustomEvent('ffr:page'));
            toast(on ? 'Added to your teams on the home screen' : 'Removed from your teams');
            return;
        }

        const leagueBtn = e.target.closest('[data-league-filter]');
        if (leagueBtn) { search.league = leagueBtn.dataset.leagueFilter; applyTeamSearch(); return; }

        const a = e.target.closest('a[href]');
        if (router.shouldHandle(a, e)) {
            e.preventDefault();
            if (fullPlayer.isOpen()) fullPlayer.hide();
            if (a.href !== location.href) router.go(a.href, true);
        }
    });

    document.addEventListener('input', (e) => {
        if (e.target.matches('[data-search-input]')) applyTeamSearch();
    });

    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && resumeScreen.el && !resumeScreen.el.hidden) { resumeScreen.hide(); return; }
        if (e.key === 'Escape' && fullPlayer.isOpen()) { fullPlayer.close(); return; }
        if (e.code === 'Space' && player.stationId && !e.target.closest('input, textarea, select, button, a, [contenteditable]')) {
            e.preventDefault();
            player.toggle();
        }
    });

    window.addEventListener('popstate', () => {
        if (fullPlayer.isOpen()) { fullPlayer.hide(); return; }
        router.go(location.href, false);
    });

    window.addEventListener('offline', () => toast('You are offline'));

    // ---------- Start ----------
    function start() {
        fullPlayer.el = $('#fullPlayer');
        resumeScreen.el = $('#resumeScreen');
        player.init();
        initPage();

        // Shared links: ?radioId=<station id> loads that station, ready to play
        const params = new URLSearchParams(location.search);
        const radioId = params.get('radioId');
        if (radioId && station(radioId)) {
            const slug = (location.pathname.match(/^\/teams\/([^/]+)\//) || [])[1] || null;
            player.stationId = radioId;
            player.teamSlug = team(slug) ? slug : null;
            player.setStatus('paused');
            toast('Tap play to listen to ' + player.headline());
        }

        if (resumeScreen.shouldShow()) resumeScreen.show();
        if (params.has('resume') || params.has('from')) {
            params.delete('resume'); params.delete('from');
            const qs = params.toString();
            history.replaceState(history.state, '', location.pathname + (qs ? '?' + qs : '') + location.hash);
        }

        if ('serviceWorker' in navigator) {
            window.addEventListener('load', () => navigator.serviceWorker.register('/sw.js').catch(() => {}));
        }
    }

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
    else start();

    // Small debugging/console API
    window.radioPlayer = player;
})();
